mapper.select:
with recursive branch_tree(id, parent_id, clan_id, visited_ids) as (
  select b.id, b.parent_id, b.clan_id, array[b.id]
  from branch b
  where b.id=#{ancestorId}
    and b.clan_id=#{clanId}
  union all
  select child.id, child.parent_id, child.clan_id, parent.visited_ids || child.id
  from branch child
  join branch_tree parent on child.parent_id=parent.id
  where child.clan_id=#{clanId}
    and not child.id=any(parent.visited_ids)
)
select exists(select 1 from branch_tree where id=#{candidateId})
